/**
 * `bun run doug-team:build` (docs/adr/doug-0020-time-doug.md): the Doug team's material, `src/doug-team/agents/*.md` and
 * `src/doug-team/skills/<slug>/SKILL.md`, written into `src/doug-team/files.gen.ts` as text, so the server reads it
 * from its own bundle and never from a folder beside it. `test/doug-team.test.ts` fails while the generated file
 * differs from what this writes.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

export const DOUG_TEAM_DIR = join(import.meta.dir, "../src/doug-team");
export const GENERATED = join(DOUG_TEAM_DIR, "files.gen.ts");

const sorted = (names: string[]) => [...names].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));

/** The generated file's text, read from the material as it is now. */
export function renderDougTeamFiles(dir = DOUG_TEAM_DIR) {
  const agents = sorted(readdirSync(join(dir, "agents")).filter((f) => f.endsWith(".md"))).map(
    (f) => [f.slice(0, -3), readFileSync(join(dir, "agents", f), "utf8")] as const,
  );
  const skills = sorted(
    readdirSync(join(dir, "skills"), { withFileTypes: true })
      .filter((d) => d.isDirectory())
      .map((d) => d.name),
  ).map((slug) => [slug, readFileSync(join(dir, "skills", slug, "SKILL.md"), "utf8")] as const);
  const entries = (list: readonly (readonly [string, string])[]) =>
    list.map(([k, v]) => `  ${JSON.stringify(k)}: ${JSON.stringify(v)},`).join("\n");
  return [
    "// Generated by `bun run doug-team:build` from agents/*.md and skills/*/SKILL.md: edit those, then run it.",
    "",
    "/** Each agent template's Markdown (frontmatter and instructions), by its file's name. */",
    "export const AGENT_FILES: Readonly<Record<string, string>> = {",
    entries(agents),
    "};",
    "",
    "/** Each house skill's SKILL.md, by its folder's name. */",
    "export const SKILL_FILES: Readonly<Record<string, string>> = {",
    entries(skills),
    "};",
    "",
  ].join("\n");
}

if (import.meta.main) {
  writeFileSync(GENERATED, renderDougTeamFiles());
  console.log(`wrote ${GENERATED}`);
}
